'use strict';
(() => {
    let summary=null,editing=null,editSequence=0,filters={},busy=false,renderSequence=0;const knownFiles=new Map();
    const routes={posts:'article',pages:'page',jobs:'job',procurement:'procurement',albums:'album',downloads:'download',people:'person',events:'event',banners:'banner',services:'service',videos:'video',newsletters:'newsletter'};
    const statusText=p=>p.deleted_at?'อยู่ในถังขยะ':p.scheduled_at?'ตั้งเวลาแล้ว':p.status==='published'?(p.has_draft?'เผยแพร่ / มีร่างแก้ไข':'เผยแพร่แล้ว'):'ฉบับร่าง';
    const icon=path=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="${path}"/></svg>`;
    const paper=()=>icon('M5 3h10l4 4v14H5zM14 3v5h5M9 12h6M9 16h6');
    const input=(label,name,value='',type='text',extra='')=>`<label class="desk-field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value??'')}" ${extra}></label>`;
    const area=(label,name,value='',extra='')=>`<label class="desk-field"><span>${label}</span><textarea name="${name}" rows="3" ${extra}>${esc(value??'')}</textarea></label>`;
    const select=(label,name,options,value)=>`<label class="desk-field"><span>${label}</span><select name="${name}">${Object.entries(options).map(([k,v])=>`<option value="${esc(k)}" ${String(value??'')===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
    const url=p=>`${CMS.base}/portal/${summary.types[p.draft?.content_type||p.content_type]?.route||'news'}/${encodeURIComponent(p.slug)}`;
    const image=(id,alt='',cls='')=>id?`<img class="${cls}" src="${mediaUrl(id)}" alt="${esc(alt)}">`:`<span class="desk-file-symbol ${cls}">${paper()}</span>`;
    const title=(eyebrow,name,desc,actions='')=>heading(eyebrow,name,desc,actions);
    const reportError=error=>{const box=document.querySelector('#desk-error');if(box)box.textContent=error.message;toast(error.message,true);};
    async function refreshSummary(){summary=await request('/api/site/state');return summary;}
    async function upload(file,folder='ทั่วไป',onComplete=null){
        const body=new FormData();body.append('file',file);body.append('folder',folder);body.append('alt',file.name.replace(/\.[^.]+$/,''));
        uploadCount++;
        try{const result=window.SchoolUploadQueue?await window.SchoolUploadQueue.send(file,folder,onComplete):await request('/api/site/media','POST',body);knownFiles.set(result.id,result);return result;}finally{uploadCount--;}
    }
    function bindLinks(){root.querySelectorAll('[data-desk-go]').forEach(button=>button.onclick=()=>location.hash=button.dataset.deskGo);}
    async function library(kind,callback,page=1,q=''){
        const result=await request('/api/site/media?'+new URLSearchParams({page:String(page),...(kind?{kind}:{}),...(q?{q}:{})}));const dialog=document.querySelector('#media-picker');
        result.data.forEach(file=>knownFiles.set(file.id,file));document.querySelector('#media-heading').textContent=kind==='document'?'เลือกเอกสารจากคลัง':'เลือกจากคลังสื่อ';
        document.querySelector('#media-items').innerHTML=`<label class="desk-field"><span>ค้นหาไฟล์ในคลัง</span><input id="picker-search" type="search" value="${esc(q)}" placeholder="ชื่อไฟล์หรือคำอธิบาย"></label><div class="desk-library">${result.data.map(file=>`<button type="button" data-desk-media="${file.id}">${file.mime.startsWith('image/')?image(file.id,file.alt):paper()}<span>${esc(file.alt||file.original_name||'ไฟล์ #'+file.id)}</span><small>${esc(file.folder)} · ${Math.ceil(file.bytes/1024)} KB</small></button>`).join('')||'<p class="desk-empty">ยังไม่มีไฟล์ตามเงื่อนไขนี้</p>'}</div><div class="desk-pagination">${result.current_page>1?`<button data-picker-page="${result.current_page-1}">ก่อนหน้า</button>`:''}<span>หน้า ${result.current_page} / ${result.last_page} · ${result.total} ไฟล์</span>${result.current_page<result.last_page?`<button data-picker-page="${result.current_page+1}">ถัดไป</button>`:''}</div>`;
        document.querySelectorAll('[data-desk-media]').forEach(button=>button.onclick=()=>{dialog.close();callback(Number(button.dataset.deskMedia));});
        document.querySelectorAll('[data-picker-page]').forEach(b=>b.onclick=()=>library(kind,callback,Number(b.dataset.pickerPage),q).catch(reportError));
        let timer;document.querySelector('#picker-search').oninput=e=>{const query=e.target.value;clearTimeout(timer);timer=setTimeout(async()=>{try{await library(kind,callback,1,query);const field=document.querySelector('#picker-search');field.focus();field.setSelectionRange(query.length,query.length);}catch(error){reportError(error);}},300);};
        if(!dialog.open)dialog.showModal();
    }
        function home(){
        const c=summary.counts,theme=data.theme.published,ico=name=>window.SchoolIcons.render(name);
        const kindIcon={posts:'megaphone',pages:'document',jobs:'briefcase',procurement:'clipboard',albums:'image',downloads:'download',people:'people',events:'calendar',banners:'flag',services:'link',videos:'video',newsletters:'mail'};
        const stats=[[c.published,'เผยแพร่แล้ว','check','posts'],[c.draft,'ฉบับร่าง','edit','posts'],[c.scheduled,'ตั้งเวลาเผยแพร่','clock','posts'],[c.messages,'ข้อความใหม่','mail','inbox'],[c.media,'ไฟล์ในคลัง','image','media']];
        const quick=[['theme','ธีมและสีโรงเรียน','palette'],['homepage','จัดหน้าแรก','home'],['menus','เมนูเว็บไซต์','menu'],['profile','ข้อมูลโรงเรียน','building'],['media','คลังสื่อ','image'],['inbox','ข้อความติดต่อ','inbox'],['categories','หมวดเนื้อหา','folder'],['trash','ถังขยะ','trash']];
        root.innerHTML=`<div class="sg-pagehead"><div><h1>ภาพรวมเว็บไซต์</h1><p>สถานะเว็บไซต์ งานที่ค้างอยู่ และทางลัดไปยังเนื้อหาแต่ละประเภท</p></div><div class="sg-pagehead-actions"><button class="primary" data-desk-go="compose/article">${ico('plus')}เขียนข่าวใหม่</button><a class="quiet-button" href="${CMS.base}/portal" target="_blank" rel="noopener">${ico('external')}ดูหน้าบ้าน</a></div></div>`+
            `<section class="sg-site glass" aria-label="เว็บไซต์โรงเรียน"><div class="sg-browser" aria-hidden="true"><div class="sg-browser-bar"><i></i><i></i><i></i><span>${esc(CMS.base)}/portal</span></div><div class="sg-browser-view">${theme.hero_media_id?`<img src="${mediaUrl(theme.hero_media_id)}" alt="">`:''}<div class="sg-browser-copy"><strong>${esc(theme.school_name)}</strong><small>${esc(theme.tagline||'')}</small></div></div></div>`+
            `<div class="sg-site-copy"><small>เว็บไซต์โรงเรียน</small><h2>${esc(theme.school_name)}</h2><p>${esc(theme.tagline||'')}</p><div class="sg-site-actions"><a class="primary quiet-button" href="${CMS.base}/portal" target="_blank" rel="noopener">${ico('external')}เปิดเว็บไซต์</a><button data-desk-go="theme">${ico('palette')}ธีมหน้าบ้าน</button><button data-desk-go="homepage">${ico('home')}จัดหน้าแรก</button></div></div></section>`+
            `<div class="desk-stats sg-stats">${stats.map(([n,label,icon,route])=>`<a class="sg-stat glass" href="#${route}"><span class="sg-ico" aria-hidden="true">${ico(icon)}</span><strong>${n}</strong><span>${label}</span></a>`).join('')}</div>`+
            `<div class="sg-split"><section class="sg-kinds glass"><div class="desk-section-heading"><h2>เนื้อหาเว็บไซต์</h2><p>เลือกประเภทที่ต้องการจัดการ</p></div><div class="sg-kind-grid">${Object.entries(routes).map(([route,type])=>`<a href="#${route}" class="sg-kind"><span class="sg-ico" aria-hidden="true">${ico(kindIcon[route]||'document')}</span><span class="sg-kind-copy"><strong>${esc(summary.types[type].label)}</strong><small>${summary.by_type[type]||0} รายการ</small></span></a>`).join('')}</div></section>`+
            `<section class="sg-recent glass"><div class="desk-section-heading"><h2>แก้ไขล่าสุด</h2><button data-desk-go="posts">ดูทั้งหมด</button></div><div id="sg-recent" aria-live="polite"><p class="desk-empty">กำลังโหลด…</p></div></section></div>`+
            `<div class="desk-quick-settings sg-quick">${quick.map(([route,label,icon])=>`<a class="sg-quick-link" href="#${route}"><span class="sg-ico" aria-hidden="true">${ico(icon)}</span>${label}</a>`).join('')}</div>`;
        bindLinks();
        const token=++renderSequence;
        request('/api/site/content?page=1').then(result=>{
            if(token!==renderSequence)return;const box=document.querySelector('#sg-recent');if(!box)return;
            box.innerHTML=result.data.length?`<ul class="sg-recent-list">${result.data.slice(0,6).map(p=>`<li><a href="#compose/${p.content_type}/${p.id}">${p.cover_media_id?`<img class="sg-thumb" src="${mediaUrl(p.cover_media_id)}" alt="">`:`<span class="sg-thumb sg-thumb-icon" aria-hidden="true">${ico(kindIcon[Object.keys(routes).find(k=>routes[k]===p.content_type)]||'document')}</span>`}<span class="sg-recent-copy"><strong>${esc(p.title)}</strong><small>${esc(summary.types[p.content_type].label)} · ${dateLabel(p.updated_at)}</small></span><span class="tag ${p.has_draft?'warm':p.status==='published'?'ok':''}">${statusText(p)}</span></a></li>`).join('')}</ul>`:'<p class="desk-empty">ยังไม่มีเนื้อหา เริ่มจากปุ่ม “เขียนข่าวใหม่”</p>';
        }).catch(()=>{const box=document.querySelector('#sg-recent');if(box)box.innerHTML='<p class="desk-empty">โหลดรายการล่าสุดไม่ได้</p>';});
    }
async function list(page='posts',pageNumber=1){
        const type=routes[page],filter=filters[page]||{q:'',status:''};const token=++renderSequence;
        const params=new URLSearchParams({page:String(pageNumber),...(type?{type}:{}),...(page==='trash'?{trash:'1'}:{}),...(filter.q?{q:filter.q}:{}),...(filter.status?{status:filter.status}:{})});
        const result=await request('/api/site/content?'+params);if(token!==renderSequence)return;
        const name=page==='trash'?'ถังขยะ':summary.types[type].label;
        root.innerHTML=title('จัดการเนื้อหา',name,page==='trash'?'คืนรายการเป็นฉบับร่างได้ โดยไม่เผยแพร่ทันที':'ค้นหา จัดการร่าง และเผยแพร่เนื้อหาในหมวดนี้',page==='trash'?'':`<a class="quiet-button" href="${CMS.base}/portal/${summary.types[type].route}" target="_blank" rel="noopener">เปิดหน้าบ้านหมวดนี้</a><button class="primary" data-desk-go="compose/${type}">เพิ่ม${esc(summary.types[type].singular)}</button>`)+
            `<div class="desk-list-filters"><input type="search" id="desk-content-search" aria-label="ค้นหาเนื้อหา" placeholder="ค้นหาหัวข้อ" value="${esc(filter.q)}"><select id="desk-content-status" aria-label="สถานะเนื้อหา"><option value="">ทุกสถานะ</option>${[['draft','ฉบับร่าง'],['published','เผยแพร่แล้ว'],['scheduled','ตั้งเวลาแล้ว']].map(([key,label])=>`<option value="${key}" ${filter.status===key?'selected':''}>${label}</option>`).join('')}</select><span>${result.total} รายการ</span></div>`+
            `<section class="desk-list glass">${result.data.map(p=>`<article class="desk-content-row">${image(p.cover_media_id,p.title,'desk-list-cover')}<div class="desk-row-copy"><span class="desk-row-category">${esc(summary.types[p.content_type].label)} · ${esc(summary.categories.find(c=>c.slug===p.category)?.label||p.category)}</span><h2>${esc(p.title)}</h2><p>${dateLabel(p.updated_at)} <span class="tag ${p.has_draft?'warm':''}">${statusText(p)}</span></p></div><div class="desk-row-actions">${page==='trash'?`<button data-content-action="restore" data-id="${p.id}" data-version="${p.version}">คืนเป็นร่าง</button>`:`<button data-desk-go="compose/${p.content_type}/${p.id}">แก้ไข</button><a class="quiet-button" href="${CMS.base}/content-preview/${p.id}" target="_blank" rel="noopener">ตัวอย่าง</a>${p.status==='published'?`<button data-content-action="unpublish" data-id="${p.id}" data-version="${p.version}">หยุดเผยแพร่</button>`:''}<button class="desk-danger" data-content-action="trash" data-id="${p.id}" data-version="${p.version}">ย้ายถังขยะ</button>`}</div></article>`).join('')||`<div class="desk-empty"><p>ยังไม่มีรายการ${page==='trash'?'ในถังขยะ':'ในหมวดนี้'}</p>${page==='trash'?'':`<button class="primary" data-desk-go="compose/${type}">เพิ่ม${esc(summary.types[type].singular)}</button>`}</div>`}</section>`+
            `<div class="desk-pagination">${result.current_page>1?'<button data-list-page="'+(result.current_page-1)+'">ก่อนหน้า</button>':''}<span>หน้า ${result.current_page} / ${result.last_page}</span>${result.current_page<result.last_page?'<button data-list-page="'+(result.current_page+1)+'">ถัดไป</button>':''}</div>`;
        bindLinks();let timer;
        document.querySelector('#desk-content-search').oninput=e=>{const q=e.target.value;clearTimeout(timer);timer=setTimeout(()=>{filters[page]={...filter,q};list(page).then(()=>{const field=document.querySelector('#desk-content-search');if(field){field.focus();field.setSelectionRange(q.length,q.length);}}).catch(reportError);},350);};
        document.querySelector('#desk-content-status').onchange=e=>{filters[page]={...filter,q:document.querySelector('#desk-content-search').value,status:e.target.value};list(page).catch(reportError);};
        root.querySelectorAll('[data-list-page]').forEach(b=>b.onclick=()=>list(page,Number(b.dataset.listPage)).catch(reportError));
        root.querySelectorAll('[data-content-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await request('/api/site/content/'+b.dataset.id+'/action','POST',{version:Number(b.dataset.version),action:b.dataset.contentAction});await refreshSummary();await list(page,pageNumber);toast('บันทึกการเปลี่ยนแปลงแล้ว');}catch(error){b.disabled=false;reportError(error);}});
    }
    function defaultEntry(type){return {id:null,version:0,status:'draft',slug:'',revisions:[],draft:{content_type:type,title:'',body:'',excerpt:'',category:summary.types[type].category,cover_media_id:null,is_pinned:false,metadata:{body_format:'html',source_kind:'original',attachments:[],gallery:[]}}};}
    const draftKey=()=>`school-content:${CMS.user.school_id}:${CMS.user.id}:${editing?.id||editing?.draft.content_type||'new'}`;
    function readEntry(){
        const form=document.querySelector('#content-form');if(!form||!editing)return null;const meta={...editing.draft.metadata};
        for(const element of form.querySelectorAll('[data-meta]')){
            const key=element.dataset.meta;meta[key]=element.type==='checkbox'?element.checked:element.type==='number'?(element.value===''?null:Number(element.value)):(element.value||null);
        }
        meta.tags=(form.querySelector('[data-tags]')?.value||'').split(',').map(x=>x.trim()).filter(Boolean);meta.body_format='html';meta.attachments=editing.draft.metadata.attachments||[];meta.gallery=editing.draft.metadata.gallery||[];
        return {title:form.elements.title.value.trim(),body:document.querySelector('#rich-body').innerHTML,excerpt:form.elements.excerpt.value,category:form.elements.category.value,content_type:editing.draft.content_type,cover_media_id:editing.draft.cover_media_id||null,is_pinned:form.elements.is_pinned.checked,metadata:meta};
    }
    function rememberEntry(){const fields=readEntry();if(fields&&Object.keys(fields).some(key=>JSON.stringify(fields[key])!==JSON.stringify(editing.draft[key])))try{sessionStorage.setItem(draftKey(),JSON.stringify({fields,version:editing.version}));}catch{}}
    function metaFields(type,meta){
        const m=(label,key,value='',t='text',extra='')=>input(label,key,value,t,`data-meta="${key}" ${extra}`);
        const ma=(label,key,value='')=>area(label,key,value,`data-meta="${key}"`);
        const ms=(label,key,options,value)=>select(label,key,options,value).replace('<select name=',`<select data-meta="${key}" name=`);
        let html='';
        if(['job','procurement'].includes(type))html+=`<section class="desk-editor-card glass"><h2>ข้อมูลประกาศ</h2><div class="desk-fields-two">${ms('ประเภทข้อมูล','source_kind',{original:'ประกาศของโรงเรียน',mock:'ข้อมูลตัวอย่างของโรงเรียน',reference:'อ้างอิงประกาศโรงเรียนจริง'},meta.source_kind||'original')}${m('โรงเรียนผู้ออกประกาศ','source_school',meta.source_school)}${m('ลิงก์ประกาศต้นฉบับ (https)','source_url',meta.source_url,'url')}${m('วันที่ต้นทาง','source_date',meta.source_date,'date')}${m('วันที่ตรวจแหล่งอ้างอิง','checked_on',meta.checked_on,'date')}${m('สิ้นสุดกำหนด','deadline',meta.deadline,'date')}</div><p class="desk-help">รายการอ้างอิงต้องมีชื่อโรงเรียนและลิงก์ต้นฉบับ ประกาศที่พ้นวันกำหนดจะแสดงสถานะย้อนหลัง</p>${type==='job'?`<div class="desk-fields-two">${m('ตำแหน่ง','position',meta.position)}${m('จำนวนอัตรา','positions',meta.positions,'number','min="1" max="999"')}${m('เริ่มรับสมัคร','opens_on',meta.opens_on,'date')}${m('ค่าตอบแทนตามประกาศ','salary',meta.salary)}</div>${ma('คุณสมบัติและข้อมูลเพิ่มเติม','qualification',meta.qualification)}`:`<div class="desk-fields-two">${ms('ขั้นตอนประกาศ','stage',{information:'ข้อมูลประกอบ',tor:'ร่าง TOR',invitation:'เชิญชวน',award:'ประกาศผู้ชนะ',contract:'สัญญา',cancelled:'ยกเลิก'},meta.stage||'information')}${ms('วิธีจัดหา','method',{'e-bidding':'ประกวดราคาอิเล็กทรอนิกส์',specific:'เฉพาะเจาะจง',selection:'คัดเลือก',other:'ตามประกาศ'},meta.method||'other')}${m('เลขที่ประกาศ','document_no',meta.document_no)}${m('วงเงินตามประกาศ (บาท)','budget',meta.budget,'number','min="0" step="0.01"')}</div>`}</section>`;
        if(type==='event')html+=`<section class="desk-editor-card glass"><h2>วันเวลาและสถานที่</h2><div class="desk-fields-two">${m('เริ่มกิจกรรม','starts_at',meta.starts_at,'datetime-local')}${m('สิ้นสุดกิจกรรม','ends_at',meta.ends_at,'datetime-local')}</div>${m('สถานที่','location',meta.location)}</section>`;
        if(type==='person')html+=`<section class="desk-editor-card glass"><h2>ข้อมูลบุคลากรที่เผยแพร่</h2>${m('ตำแหน่งงาน','job_title',meta.job_title)}${m('กลุ่มงาน','department',meta.department)}${m('อีเมลติดต่อที่เปิดเผยได้','contact_email',meta.contact_email,'email')}</section>`;
        if(['banner','service'].includes(type))html+=`<section class="desk-editor-card glass"><h2>ลิงก์และลำดับ</h2>${m('ลิงก์ปลายทาง (/portal/... หรือ https)','url',meta.url)}${m('ลำดับแสดงผล','sort_order',meta.sort_order||0,'number','min="0" max="9999"')}${type==='banner'?ms('ตำแหน่ง','placement',{notice:'แถบประกาศ',hero:'ส่วนต้อนรับ',sidebar:'แถบประกาศเพิ่มเติม',popup:'ป๊อบอัพ'},meta.placement||'notice'):''}</section>`;
        if(type==='banner')html+=`<section class="desk-editor-card glass"><h2>ช่วงเวลาแสดง banner</h2><div class="desk-fields-two">${m('เริ่มแสดง (เวลาไทย)','starts_at',meta.starts_at,'datetime-local')}${m('หยุดแสดง (เวลาไทย)','ends_at',meta.ends_at,'datetime-local')}</div><p class="desk-help">เว้นว่างเพื่อแสดงต่อเนื่อง ระบบใช้ช่วงเวลานี้เฉพาะ banner บนหน้าแรก</p></section>`;
        if(type==='banner')html+=`<section class="desk-editor-card glass" id="hero-detail-fields" ${meta.placement==='hero'?'':'hidden'}><h2>ออกแบบสไลด์หน้าแรก</h2>${m('ข้อความนำสั้น','kicker',meta.kicker)}<div class="desk-fields-two">${m('ข้อความปุ่มหลัก','button_label',meta.button_label)}${m('ข้อความปุ่มรอง','secondary_label',meta.secondary_label)}</div>${m('ลิงก์ปุ่มรอง','secondary_url',meta.secondary_url)}<div class="desk-fields-two">${m('จุดโฟกัสแนวนอน (%)','focal_x',meta.focal_x??50,'number','min="0" max="100"')}${m('จุดโฟกัสแนวตั้ง (%)','focal_y',meta.focal_y??50,'number','min="0" max="100"')}${m('ความเข้มพื้นข้อความ','overlay',meta.overlay??.75,'number','min="0.3" max="0.85" step="0.01"')}${ms('ตำแหน่งข้อความ','text_align',{left:'ด้านซ้าย',center:'กึ่งกลาง',right:'ด้านขวา'},meta.text_align||'left')}</div><h3>ภาพสำหรับมือถือ (เลือกเพิ่มเติมได้)</h3><input type="number" data-meta="mobile_media_id" name="mobile_media_id" value="${meta.mobile_media_id||''}" hidden><div id="mobile-hero-image">${image(meta.mobile_media_id,'ภาพสไลด์มือถือ')}</div><button type="button" id="pick-mobile-hero">เลือกรูปมือถือ</button><button type="button" id="clear-mobile-hero">ใช้ภาพเดียวกับคอมพิวเตอร์</button><p class="desk-help">หัวข้อและคำโปรยด้านบนคือข้อความบนสไลด์ ภาพปกคือภาพใหญ่ กดดูตัวอย่างก่อนเผยแพร่ได้</p></section>`;
        if(type==='video')html+=`<section class="desk-editor-card glass"><h2>วีดิทัศน์</h2>${m('YouTube หรือ Vimeo (https)','video_url',meta.video_url,'url')}<p class="desk-help">หรือใช้ MP4 ในคลัง ไม่เกิน 10 MB ถ้าเลือกไฟล์ในคลัง ระบบจะแสดงไฟล์นั้นก่อนลิงก์ภายนอก</p><input type="number" hidden data-meta="video_media_id" value="${meta.video_media_id||''}" id="video-media-id"><p id="video-selection">${meta.video_media_id?'เลือกไฟล์ #'+Number(meta.video_media_id):'ยังไม่ได้เลือกไฟล์ MP4'}</p><button type="button" id="choose-local-video">เลือก MP4 จากคลัง</button><button type="button" id="clear-local-video">นำไฟล์ออก</button><label class="desk-upload-small">อัปโหลด MP4<input type="file" id="local-video-file" accept="video/mp4,.mp4"></label></section>`;
        if(type==='newsletter')html+=`<section class="desk-editor-card glass"><h2>ข้อมูลฉบับจดหมายข่าว</h2><div class="desk-fields-two">${m('ฉบับที่','issue_no',meta.issue_no)}${m('วันที่ออกจดหมายข่าว','issued_on',meta.issued_on,'date')}</div><p class="desk-help">แนบ PDF ฉบับเต็มด้านล่าง หรือเผยแพร่เนื้อหาดิจิทัลในหน้านี้</p></section>`;
        return html;
    }
    async function compose(type,id,placement=null){
        if(!summary.types[type])type='article';const hash=location.hash;
        editing=id?await request('/api/site/content/'+id):defaultEntry(type);if(location.hash!==hash)return;type=editing.draft.content_type;(editing.media||[]).forEach(file=>knownFiles.set(file.id,file));
        if(placement&&!id)editing.draft.metadata.placement=placement;if(editing.deleted_at){location.hash='trash';return;}
        let recovered=false;try{const saved=JSON.parse(sessionStorage.getItem(draftKey())||'null');if(saved&&saved.version===editing.version){editing.draft=saved.fields;recovered=true;}}catch{}
        const entry=editing.draft,meta={...(entry.metadata||{})};editing.draft.metadata=meta;
        const htmlBody=meta.body_format==='html'?entry.body:esc(entry.body).replace(/\n/g,'<br>');
        root.innerHTML=title('เขียนและแก้ไขเนื้อหา',editing.id?'แก้ไข'+summary.types[type].singular:'เพิ่ม'+summary.types[type].singular,'เขียนเนื้อหา เลือกภาพ และดูตัวอย่างก่อนเผยแพร่',`<button type="submit" form="content-form" name="intent" value="draft" data-content-save>เก็บร่าง</button><button type="submit" form="content-form" name="intent" value="publish" class="primary" data-content-save>${editing.status==='published'?'เผยแพร่การแก้ไข':'เผยแพร่'}</button>`)+
            `<form id="content-form" class="desk-editor-layout"><div class="desk-editor-main"><section class="desk-editor-card glass">${type==='banner'?area('หัวข้อ (ขึ้นบรรทัดได้)','title',entry.title,'required maxlength="180" class="desk-title-input"'):input('หัวข้อ','title',entry.title,'text','required maxlength="180" placeholder="เริ่มเรื่องราวของคุณที่นี่" class="desk-title-input"')}<div class="desk-rich-toolbar" role="toolbar" aria-label="จัดรูปแบบข้อความ">${[['bold','ตัวหนา','B'],['italic','ตัวเอียง','I'],['h2','หัวข้อรอง','H2'],['insertUnorderedList','รายการหัวข้อ','รายการ'],['createLink','แทรกลิงก์','ลิงก์'],['removeFormat','ล้างรูปแบบ','ล้าง']].map(([command,label,text])=>`<button type="button" data-rich-command="${command}" aria-label="${label}">${text}</button>`).join('')}</div><div id="rich-body" class="desk-rich-body" role="textbox" aria-label="เนื้อหา" aria-multiline="true" contenteditable="true">${htmlBody}</div><p class="desk-help">วางข้อความแล้วใช้ปุ่มจัดรูปแบบ เพื่อให้เนื้อหาอ่านง่าย</p>${area('คำโปรย (เว้นว่างเพื่อย่อให้อัตโนมัติ)','excerpt',entry.excerpt,'maxlength="300"')}${input('แท็ก (คั่นด้วย comma)','tags',(meta.tags||[]).join(', '),'text','data-tags maxlength="650"')}</section>${metaFields(type,meta)}
            <section class="desk-editor-card glass"><div class="desk-section-heading"><h2>เอกสารแนบ</h2><button type="button" id="add-attachment">เลือกจากคลัง</button></div><label class="desk-upload-small">อัปโหลดเอกสาร<input id="attachment-file" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.csv,.txt,.zip" multiple></label><div id="content-attachments"></div></section>
            ${type==='album'?'<section class="desk-editor-card glass"><div class="desk-section-heading"><h2>รูปในอัลบั้ม</h2><button type="button" id="add-gallery">เลือกจากคลัง</button></div><label class="desk-upload-small">อัปโหลดรูปหลายไฟล์<input id="gallery-file" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div id="content-gallery" class="desk-gallery-picks"></div></section>':''}
            <section class="desk-editor-card glass"><h2>ข้อมูลค้นหาและแชร์</h2>${input('ชื่อที่ใช้ในการค้นหา (เว้นว่างใช้หัวข้อ)','seo_title',meta.seo_title,'text','data-meta="seo_title" maxlength="160"')}${area('คำอธิบายสำหรับค้นหาและแชร์','seo_description',meta.seo_description,'data-meta="seo_description" maxlength="300"')}</section></div>
            <aside class="desk-editor-side"><section class="desk-editor-card glass"><h2>การเผยแพร่</h2><p><span class="tag" id="content-status-tag">${statusText(editing)}</span></p>${select('หมวดเนื้อหา','category',Object.fromEntries(summary.categories.map(c=>[c.slug,c.label])),entry.category)}<label class="desk-check-label"><input name="is_pinned" type="checkbox" ${entry.is_pinned?'checked':''}>ปักหมุดรายการนี้</label>${input('วันและเวลาที่ต้องการเผยแพร่','scheduled_at',editing.scheduled_at?new Date(editing.scheduled_at.replace(' ','T')+'Z').toLocaleString('sv-SE',{timeZone:'Asia/Bangkok'}).slice(0,16).replace(' ','T'):'','datetime-local')}<button type="submit" name="intent" value="schedule" data-content-save>ตั้งเวลาเผยแพร่</button><p class="desk-help">วันและเวลาไทย · ฉบับร่างล่าสุดจะเผยแพร่เมื่อถึงกำหนด</p><a id="content-preview" class="desk-preview-link" href="${CMS.base}${meta.placement==='hero'?'/hero-preview/':'/content-preview/'}${editing.id||''}" target="_blank" rel="noopener" ${editing.id?'':'hidden'}>ดูตัวอย่างร่างที่บันทึก</a><a id="content-live" class="desk-preview-link" href="${editing.id?url(editing):'#'}" target="_blank" rel="noopener" ${editing.status==='published'?'':'hidden'}>เปิดรายการที่เผยแพร่</a></section>
            <section class="desk-editor-card glass"><h2>รูปปก</h2><div id="content-cover-preview">${image(entry.cover_media_id,'รูปปก')}</div><label class="desk-upload-small">อัปโหลดรูป<input id="content-cover-file" type="file" accept="image/jpeg,image/png,image/webp"></label><button type="button" id="choose-content-cover">เลือกจากคลัง</button><button type="button" id="clear-content-cover">ไม่ใช้รูปปก</button></section>
            <section class="desk-editor-card glass"><h2>ประวัติการเผยแพร่</h2><p class="desk-help">คืนเวอร์ชันเป็นร่างก่อน ข่าวเดิมยังไม่เปลี่ยนจนกดเผยแพร่</p><div id="content-revisions">${revisionControls()}</div></section></aside>
            <div class="desk-savebar glass"><p id="content-save-status">${recovered?'คืนข้อความที่ยังไม่บันทึกในแท็บนี้แล้ว':'พร้อมเขียนเนื้อหา'}</p><div><button type="submit" name="intent" value="draft" data-content-save>เก็บร่าง</button><button type="submit" name="intent" value="publish" class="primary" data-content-save>เผยแพร่</button></div></div><p class="desk-error" id="desk-error" role="alert"></p></form>`;
        const form=document.querySelector('#content-form');
        const changed=()=>{editSequence++;document.querySelector('#content-save-status').textContent='มีการแก้ไขที่ยังไม่บันทึก';rememberEntry();};
        form.oninput=changed;form.onchange=changed;form.onsubmit=saveEntry;
        form.querySelectorAll('[data-rich-command]').forEach(button=>{button.onmousedown=e=>e.preventDefault();button.onclick=()=>{const command=button.dataset.richCommand;if(command==='h2')document.execCommand('formatBlock',false,'h2');else if(command==='createLink'){const target=prompt('วางลิงก์ https หรือเส้นทางเว็บไซต์');if(target&&(/^(https:\/\/|\/(?!\/)|#[A-Za-z])/.test(target)))document.execCommand('createLink',false,target);}else document.execCommand(command,false);changed();};});
        document.querySelector('#rich-body').onpaste=e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));};
        const targetEntry=editing;
        const setCover=id=>{if(editing!==targetEntry||!form.isConnected)return;editing.draft.cover_media_id=id;document.querySelector('#content-cover-preview').innerHTML=image(id,'รูปปก');changed();};
        document.querySelector('#choose-content-cover').onclick=()=>library('image',setCover).catch(reportError);document.querySelector('#clear-content-cover').onclick=()=>setCover(null);
        document.querySelector('#content-cover-file').onchange=async e=>{if(!e.target.files[0])return;try{await upload(e.target.files[0],'รูปปก',result=>setCover(result.id));toast('อัปโหลดรูปแล้ว');}catch(error){reportError(error);}};
        document.querySelector('#add-attachment').onclick=()=>library('document',id=>{const ids=editing.draft.metadata.attachments||[];if(!ids.includes(id))ids.push(id);editing.draft.metadata.attachments=ids;renderSelections();changed();}).catch(reportError);
        document.querySelector('#attachment-file').onchange=e=>uploadSelected(e.target.files,'attachments','เอกสาร',changed);
        if(type==='album'){document.querySelector('#add-gallery').onclick=()=>library('image',id=>{const ids=editing.draft.metadata.gallery||[];if(!ids.includes(id))ids.push(id);editing.draft.metadata.gallery=ids;renderSelections();changed();}).catch(reportError);document.querySelector('#gallery-file').onchange=e=>uploadSelected(e.target.files,'gallery','อัลบั้ม',changed);}
        if(type==='video'){const setVideo=id=>{if(editing!==targetEntry||!form.isConnected)return;editing.draft.metadata.video_media_id=id;document.querySelector('#video-media-id').value=id||'';document.querySelector('#video-selection').textContent=id?'เลือกไฟล์ #'+id:'ยังไม่ได้เลือกไฟล์ MP4';changed();};document.querySelector('#choose-local-video').onclick=()=>library('video',setVideo).catch(reportError);document.querySelector('#clear-local-video').onclick=()=>setVideo(null);document.querySelector('#local-video-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const result=await upload(file,'วีดิทัศน์');setVideo(result.id);toast('อัปโหลด MP4 แล้ว');}catch(error){reportError(error);}};}
        renderSelections();bindRevision();window.SchoolPresentation?.enhanceSlide(type,meta,form);window.SchoolRelease?.enhance('compose');
    }
    function revisionControls(){return editing.revisions.length?`<select id="content-revision" aria-label="เวอร์ชันที่ต้องการคืน">${editing.revisions.map(r=>`<option value="${r.id}">เวอร์ชัน ${r.version} · ${dateLabel(r.created_at)}</option>`).join('')}</select><button type="button" id="compare-content-revision">เปรียบเทียบเวอร์ชัน</button><button type="button" id="restore-content-revision">คืนเวอร์ชันเป็นร่าง</button>`:'<p class="desk-help">ประวัติจะแสดงเมื่อเผยแพร่ครั้งแรก</p>';}
    function bindRevision(){window.SchoolRelease?.bindComparison(editing); const button=document.querySelector('#restore-content-revision');if(button)button.onclick=async()=>{try{await request('/api/site/content/'+editing.id+'/action','POST',{version:editing.version,action:'revision',revision_id:Number(document.querySelector('#content-revision').value)});sessionStorage.removeItem(draftKey());await compose(editing.draft.content_type,editing.id);window.SchoolRelease?.enhance('compose');toast('คืนเวอร์ชันเป็นฉบับร่างแล้ว');}catch(error){reportError(error);}};}
    function renderSelections(){
        const meta=editing.draft.metadata,attachments=document.querySelector('#content-attachments'),gallery=document.querySelector('#content-gallery');
        if(attachments)attachments.innerHTML=(meta.attachments||[]).map(id=>`<div class="desk-attached-file"><a href="${mediaUrl(id)}" target="_blank" rel="noopener">${paper()} ${esc(knownFiles.get(id)?.alt||knownFiles.get(id)?.original_name||'เอกสารแนบ')}</a><button type="button" data-remove-attachment="${id}">นำออก</button></div>`).join('')||'<p class="desk-help">ยังไม่มีเอกสารแนบ</p>';
        if(gallery)gallery.innerHTML=(meta.gallery||[]).map(id=>`<div draggable="true" data-gallery-id="${id}">${image(id,'รูปในอัลบั้ม')}<button type="button" data-gallery-move="${id},-1" aria-label="เลื่อนภาพขึ้น">ขึ้น</button><button type="button" data-gallery-move="${id},1" aria-label="เลื่อนภาพลง">ลง</button><button type="button" data-remove-gallery="${id}">นำรูปออก</button></div>`).join('')||'<p class="desk-help">ยังไม่มีรูปในอัลบั้ม</p>';
        const moveGallery=(id,delta)=>{const ids=meta.gallery||[],from=ids.indexOf(id),to=from+delta;if(from<0||to<0||to>=ids.length)return;[ids[from],ids[to]]=[ids[to],ids[from]];renderSelections();editSequence++;rememberEntry();};root.querySelectorAll('[data-gallery-move]').forEach(b=>b.onclick=()=>{const[id,d]=b.dataset.galleryMove.split(',').map(Number);moveGallery(id,d);});let dragging=null;root.querySelectorAll('[data-gallery-id]').forEach(card=>{card.ondragstart=()=>dragging=Number(card.dataset.galleryId);card.ondragover=e=>e.preventDefault();card.ondrop=e=>{e.preventDefault();const from=meta.gallery.indexOf(dragging),to=meta.gallery.indexOf(Number(card.dataset.galleryId));if(from<0||to<0)return;const[item]=meta.gallery.splice(from,1);meta.gallery.splice(to,0,item);renderSelections();editSequence++;rememberEntry();};});
        root.querySelectorAll('[data-remove-attachment],[data-remove-gallery]').forEach(button=>button.onclick=()=>{const isGallery=!!button.dataset.removeGallery,key=isGallery?'gallery':'attachments',id=Number(button.dataset.removeGallery||button.dataset.removeAttachment);meta[key]=(meta[key]||[]).filter(x=>x!==id);renderSelections();editSequence++;rememberEntry();});
    }
    async function uploadSelected(files,key,folder,changed){const target=editing;let success=0,errors=0;for(const file of [...files]){try{await upload(file,folder,result=>{if(editing!==target||!document.querySelector('#content-form'))return;const ids=(target.draft.metadata[key]??=[]);if(!ids.includes(result.id))ids.push(result.id);renderSelections();changed();});success++;}catch(error){errors++;reportError(error);}}if(editing===target){renderSelections();changed();toast('อัปโหลดสำเร็จ '+success+' ไฟล์'+(errors?' · ไม่สำเร็จ '+errors+' ไฟล์':''),!!errors);}}
    async function saveEntry(event){
        event.preventDefault();if(busy)return;if(uploadCount){toast('กำลังอัปโหลดไฟล์ รอสักครู่แล้วบันทึกอีกครั้ง');return;}const form=event.currentTarget,intent=event.submitter?.value||'draft',payload=readEntry();if(!form.reportValidity())return;
        if(intent==='schedule'&&!form.elements.scheduled_at.value){toast('กรุณาเลือกวันเวลาเผยแพร่',true);form.elements.scheduled_at.focus();return;}
        const old=editing,oldKey=draftKey(),sequence=editSequence;busy=true;root.querySelectorAll('[data-content-save]').forEach(b=>b.disabled=true);document.querySelector('#desk-error').textContent='';
        try{
            const result=await request('/api/site/content'+(old.id?'/'+old.id:''),old.id?'PUT':'POST',{...payload,version:old.version,intent,scheduled_at:form.elements.scheduled_at.value||null});
            try{sessionStorage.removeItem(oldKey);}catch{}
            if(document.querySelector('#content-form')===form){editing=result;document.querySelector('#content-status-tag').textContent=statusText(result);root.querySelectorAll('[data-content-save][value=publish]').forEach(b=>b.textContent=result.status==='published'?'เผยแพร่การแก้ไข':'เผยแพร่');history.replaceState(null,'','#compose/'+result.draft.content_type+'/'+result.id);if(sequence===editSequence){form.elements.excerpt.value=result.draft.excerpt||'';document.querySelector('#rich-body').innerHTML=result.draft.body;sessionStorage.removeItem(draftKey());}else rememberEntry();document.querySelector('#content-save-status').textContent=(intent==='publish'?'เผยแพร่แล้ว':intent==='schedule'?'ตั้งเวลาเผยแพร่แล้ว':'เก็บร่างแล้ว')+(sequence!==editSequence?' · ยังมีการแก้ไขใหม่ที่ไม่ได้บันทึก':'');const preview=document.querySelector('#content-preview');preview.hidden=false;preview.href=CMS.base+(result.draft.metadata.placement==='hero'?'/hero-preview/':'/content-preview/')+result.id;const live=document.querySelector('#content-live');live.hidden=result.status!=='published';live.href=url(result);document.querySelector('#content-revisions').innerHTML=revisionControls();bindRevision();}
            await refreshSummary();toast(intent==='publish'?'เผยแพร่เนื้อหาแล้ว':intent==='schedule'?'ตั้งเวลาเผยแพร่แล้ว':'บันทึกฉบับร่างแล้ว');
        }catch(error){reportError(error);}finally{busy=false;root.querySelectorAll('[data-content-save]').forEach(b=>b.disabled=false);}
    }
    async function media(page=1,q='',kind=''){
        const hash=location.hash;const response=await request('/api/site/media?'+new URLSearchParams({page:String(page),q,kind}));if(hash!==location.hash)return;
        root.innerHTML=title('รูปภาพและเอกสาร','คลังสื่อและเอกสาร','รวมรูปภาพและเอกสาร สำหรับเนื้อหาบนเว็บไซต์',`<label class="desk-upload-small primary">อัปโหลดไฟล์<input id="library-upload" type="file" accept="image/jpeg,image/png,image/webp,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.csv,.txt,.zip,.mp4" multiple></label>`)+`<p class="desk-error" id="desk-error" role="alert"></p>${response.storage?`<p class="desk-help" id="media-storage">พื้นที่ไฟล์: ใช้ไป ${(response.storage.used_bytes/1048576).toFixed(1)} MB${response.storage.quota_bytes?` จาก ${Math.round(response.storage.quota_bytes/1048576)} MB (${response.storage.percent}%)`:' (ไม่จำกัดโควตา)'} · ไฟล์ละไม่เกิน ${Number(response.storage.max_upload_mb)} MB</p>`:''}<div class="desk-list-filters"><input id="media-search" type="search" aria-label="ค้นหาไฟล์" placeholder="ค้นหาชื่อหรือคำอธิบาย" value="${esc(q)}"><select id="media-kind" aria-label="ชนิดไฟล์"><option value="">ทุกชนิด</option><option value="image">รูปภาพ</option><option value="document">เอกสาร</option><option value="video">วีดิทัศน์ MP4</option></select></div><div id="desk-media-results"></div><div id="desk-media-pagination"></div>`;
        const paint=items=>{document.querySelector('#desk-media-results').innerHTML=`<div class="desk-media-grid">${items.map(file=>`<article class="glass">${file.mime.startsWith('image/')?image(file.id,file.alt):`<div class="desk-pdf-cover">${paper()}<span>${esc(file.original_name?.split('.').pop()?.toUpperCase()||'FILE')}</span></div>`}<div><h2>${esc(file.original_name||file.alt||'ไฟล์ #'+file.id)}</h2><p>${esc(file.folder)} · ${Math.ceil(file.bytes/1024)} KB</p><label>คำอธิบายภาพ / ชื่อเอกสาร<input data-file-alt="${file.id}" value="${esc(file.alt)}" maxlength="200"></label><label>โฟลเดอร์<input data-file-folder="${file.id}" value="${esc(file.folder)}" maxlength="80"></label><footer>${file.mime.startsWith('image/')?`<button data-file-variant="${file.id}">ปรับขนาดภาพ</button>`:''}<button data-file-save="${file.id}" data-version="${file.version}">บันทึก</button><a href="${mediaUrl(file.id)}" target="_blank" rel="noopener">เปิด</a><button data-file-delete="${file.id}" data-version="${file.version}" class="desk-danger">ลบ</button></footer></div></article>`).join('')||'<div class="desk-empty">ยังไม่มีไฟล์ตามเงื่อนไขนี้</div>'}</div>`;root.querySelectorAll('[data-file-variant]').forEach(b=>b.onclick=()=>window.SchoolVariants.open(items.find(f=>f.id===Number(b.dataset.fileVariant))));root.querySelectorAll('[data-file-save]').forEach(b=>b.onclick=async()=>{try{await request('/api/site/media/'+b.dataset.fileSave,'PUT',{version:Number(b.dataset.version),alt:root.querySelector(`[data-file-alt="${b.dataset.fileSave}"]`).value,folder:root.querySelector(`[data-file-folder="${b.dataset.fileSave}"]`).value});toast('บันทึกข้อมูลไฟล์แล้ว');await media();}catch(error){reportError(error);}});root.querySelectorAll('[data-file-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('ลบไฟล์ที่ไม่ได้ใช้งานนี้ถาวรหรือไม่?'))return;try{await request('/api/site/media/'+b.dataset.fileDelete,'DELETE',{version:Number(b.dataset.version)});await media();toast('ลบไฟล์แล้ว');}catch(error){reportError(error);}});window.SchoolCompact?.media();};
        const paintPages=result=>{document.querySelector('#desk-media-pagination').innerHTML=pagination(result);bindPagination(result,p=>media(p,document.querySelector('#media-search').value,document.querySelector('#media-kind').value));};paint(response.data);paintPages(response);document.querySelector('#media-kind').value=kind;let timer;const filter=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const q=document.querySelector('#media-search').value,kind=document.querySelector('#media-kind').value;try{const result=await request('/api/site/media?'+new URLSearchParams({q,kind}));if(hash!==location.hash)return;paint(result.data);paintPages(result);}catch(error){reportError(error);}},250);};
        document.querySelector('#media-search').oninput=filter;document.querySelector('#media-kind').onchange=filter;
        document.querySelector('#library-upload').onchange=async e=>{try{for(const file of [...e.target.files]){try{await upload(file);}catch(error){reportError(error);}}await refreshSummary();await media();toast('อัปโหลดไฟล์แล้ว');}catch(error){reportError(error);}};
    }
    window.CmsComplete={
        leave(){rememberEntry();editing=null;renderSequence++;},
        pickMedia:library,
        async render(parts){
            rememberEntry();editing=null;const hash=location.hash,sequence=++renderSequence;await refreshSummary();if(hash!==location.hash||sequence!==renderSequence)return;const page=document.body.dataset.cmsPage||'home';
            if(page==='home')return home();if(page==='compose'){const numeric=/^\d+$/.test(parts[1]||'');return compose(parts[1]==='slide'?'banner':numeric?'article':parts[1]||'article',numeric?Number(parts[1]):Number(parts[2])||null,parts[1]==='slide'?'hero':null);}
            if(routes[page]||page==='trash')return list(page);if(page==='media')return media();
            return additional(page);
        },
        enhanceTheme(){const menus=document.querySelector('#theme-menu-items')?.closest('.cms-control-card');if(menus){menus.hidden=true;const note=document.createElement('section');note.className='cms-control-card glass';note.innerHTML='<h2>เมนูเว็บไซต์</h2><p class="desk-help">เมนูหลายระดับจัดการแยกจากสีและธีม</p><a href="#menus">เปิดตัวจัดการเมนู</a>';menus.after(note);}},
    };
    window.addEventListener('beforeunload',rememberEntry);
    // Other complete CMS screens are installed below; all requests use the same Laravel session/CSRF.
    async function additional(page){return renderAdditional(page);}

    async function renderAdditional(page) {
        if(['profile','menus','homepage'].includes(page))return settingsPage(page);
        if(page==='categories')return categoriesPage();
        if(page==='inbox')return inbox();
        if(page==='audit')return audit();
        return home();
    }
    async function settingsPage(page){
        const s=copy(summary.settings.draft);let navigation=flattenMenus(s.navigation),sections=allSections(s.homepage_sections);
        const labels={profile:['ข้อมูลโรงเรียน','ข้อความแนะนำ ข้อมูลติดต่อ สถิติและข้อมูลสำหรับค้นหา'],menus:['เมนูเว็บไซต์','เมนูหลายระดับ เชื่อมหน้าเนื้อหาและบริการของโรงเรียน'],homepage:['จัดหน้าแรก','เลือกส่วนที่แสดงและเรียงลำดับหน้าแรกได้โดยไม่เขียนโค้ด']};
        root.innerHTML=title('ตั้งค่าเว็บไซต์',labels[page][0],labels[page][1],`<a class="quiet-button" href="${CMS.base}/theme-preview" target="_blank" rel="noopener">ตัวอย่างร่างที่บันทึก</a><button form="site-settings-form" name="intent" value="draft">เก็บร่าง</button><button form="site-settings-form" name="intent" value="publish" class="primary">ใช้บนเว็บไซต์</button>`)+
            `<form id="site-settings-form"><p class="desk-error" id="desk-error" role="alert"></p>${page==='profile'?`<div class="desk-settings-layout"><section class="desk-editor-card glass"><h2>เกี่ยวกับโรงเรียน</h2>${input('ป้ายข้อความด้านบนเว็บไซต์','badge',s.badge,'text','required maxlength="100"')}${input('ข้อความแนะนำโรงเรียน','intro_heading',s.intro_heading,'text','required maxlength="160"')}${area('คำอธิบายโรงเรียน','intro_text',s.intro_text,'maxlength="1000"')}${area('ข้อความพันธกิจสั้น','mission',s.mission,'maxlength="500"')}${input('ระดับชั้นที่เปิดสอน','levels',s.levels,'text','maxlength="180"')}${area('คำอธิบายเว็บไซต์สำหรับค้นหา','default_seo_description',s.default_seo_description,'maxlength="300"')}${input('ข้อความส่วนท้าย','footer_text',s.footer_text,'text','maxlength="250"')}</section><section class="desk-editor-card glass"><h2>ติดต่อและสถิติ</h2>${input('อีเมลโรงเรียน','email',s.email,'email','maxlength="254"')}${input('เวลาทำการ','office_hours',s.office_hours,'text','maxlength="200"')}<label class="desk-field"><span>แหล่งข้อมูลหน้าบุคลากรบนเว็บไซต์</span><select name="directory_source"><option value="manual"${s.directory_source==='personnel'?'':' selected'}>กรอกเอง (เนื้อหาประเภทบุคลากร)</option><option value="personnel"${s.directory_source==='personnel'?' selected':''}${(summary.directory_sources||[]).includes('personnel')?'':' disabled'}>ดึงจากทะเบียนบุคลากร (โมดูลบุคลากร)</option></select></label>${(summary.directory_sources||[]).includes('personnel')?'':'<p class="desk-help">ต้องเปิดโมดูลทะเบียนบุคลากรก่อน จึงจะเลือกแหล่งนี้ได้</p>'}<p class="desk-help">ชื่อ โลโก้ ที่อยู่และโทรศัพท์ปรับได้ใน <a href="#theme">หน้าปรับธีม</a></p><h3>สถิติที่แสดงหน้าแรก</h3><div id="site-statistics">${s.statistics.map(statRow).join('')}</div><button id="add-site-stat" type="button">เพิ่มสถิติ</button><h3>ลิงก์สังคมออนไลน์</h3><div id="site-social">${s.social_links.map(socialRow).join('')}</div><button id="add-site-social" type="button">เพิ่มลิงก์</button></section>${extrasCard(s)}</div>`:page==='menus'?`<section class="desk-editor-card glass"><div class="desk-section-heading"><h2>เมนูที่แสดงหน้าเว็บไซต์</h2><button type="button" id="add-site-menu">เพิ่มเมนู</button></div><p class="desk-help">ใช้ปุ่มเยื้องเพื่อทำเมนูย่อย รองรับ 3 ระดับ ลิงก์ภายในเริ่มด้วย /portal/ หรือใส่ https</p><div id="site-navigation"></div><div class="desk-menu-suggestions"><strong>ลิงก์ที่ใช้บ่อย</strong>${[['/portal','หน้าแรก'],['/portal/news','ข่าว'],['/portal/jobs','รับสมัครงาน'],['/portal/procurement','จัดซื้อจัดจ้าง'],['/portal/albums','อัลบั้ม'],['/portal/downloads','ดาวน์โหลด'],['/portal/people','บุคลากร'],['/portal/groups','กลุ่มงาน กลุ่มสาระ สมาคม และรายงาน'],['/portal/events','ปฏิทิน'],['/portal/contact','ติดต่อ']].map(([path,label])=>`<button type="button" data-suggest-path="${path}" data-suggest-label="${label}">${label}</button>`).join('')}</div><div id="site-page-suggestions"></div></section>`:`<section class="desk-editor-card glass"><div class="desk-section-heading"><h2>ส่วนประกอบหน้าแรก</h2><button type="button" id="reset-home-sections">คืนรูปแบบมาตรฐาน</button></div><p class="desk-help">ส่วนต้อนรับและสถิติอยู่ด้านบนเสมอ เลือกแสดงและเรียงส่วนเนื้อหาด้านล่าง</p><div id="site-home-sections"></div><div class="desk-add-block"><label for="homepage-page-block">เพิ่มบล็อกจากหน้าเนื้อหา</label><select id="homepage-page-block"><option value="">เลือกหน้าเนื้อหา</option></select><button type="button" id="add-homepage-block">เพิ่มส่วนเนื้อหา</button></div><a href="#pages">สร้างหน้าเนื้อหาใหม่</a> · <a href="#theme">แก้รูปต้อนรับ สี และรูปแบบการ์ดข่าว</a></section>`}<div class="desk-settings-footer"><p id="settings-status">ร่างแยกจากการตั้งค่าที่เผยแพร่อยู่</p><div><button name="intent" value="draft">เก็บร่าง</button><button class="primary" name="intent" value="publish">ใช้บนเว็บไซต์</button></div></div></form>`;
        const form=document.querySelector('#site-settings-form');
        const paintMenus=()=>{document.querySelector('#site-navigation').innerHTML=navigation.map((item,index)=>`<div class="desk-menu-row" style="--menu-level:${item.level}"><span>${String(index+1).padStart(2,'0')}</span><input data-menu-label-index="${index}" aria-label="ชื่อเมนู ${index+1}" value="${esc(item.label)}" maxlength="60" required><input data-menu-url-index="${index}" aria-label="ลิงก์เมนู ${index+1}" value="${esc(item.url)}" maxlength="1000" required><div><button type="button" data-menu-shift="${index},-1" aria-label="เลื่อนเมนูขึ้น">ขึ้น</button><button type="button" data-menu-shift="${index},1" aria-label="เลื่อนเมนูลง">ลง</button><button type="button" data-menu-indent="${index},1">เยื้อง</button><button type="button" data-menu-indent="${index},-1">ถอย</button><button type="button" data-menu-remove="${index}" class="desk-danger">นำออก</button></div></div>`).join('');
            root.querySelectorAll('[data-menu-label-index]').forEach(el=>el.oninput=()=>navigation[Number(el.dataset.menuLabelIndex)].label=el.value);
            root.querySelectorAll('[data-menu-url-index]').forEach(el=>el.oninput=()=>navigation[Number(el.dataset.menuUrlIndex)].url=el.value);
            root.querySelectorAll('[data-menu-shift]').forEach(b=>b.onclick=()=>{const [i,delta]=b.dataset.menuShift.split(',').map(Number),target=i+delta;if(target<0||target>=navigation.length)return;[navigation[i],navigation[target]]=[navigation[target],navigation[i]];paintMenus();});
            root.querySelectorAll('[data-menu-indent]').forEach(b=>b.onclick=()=>{const [i,delta]=b.dataset.menuIndent.split(',').map(Number);navigation[i].level=Math.min(2,Math.max(0,navigation[i].level+delta));paintMenus();});
            root.querySelectorAll('[data-menu-remove]').forEach(b=>b.onclick=()=>{navigation.splice(Number(b.dataset.menuRemove),1);paintMenus();});
        };
        if(page==='menus'){
            paintMenus();document.querySelector('#add-site-menu').onclick=()=>{navigation.push({label:'เมนูใหม่',url:'/portal',level:0});paintMenus();};
            root.querySelectorAll('[data-suggest-path]').forEach(b=>b.onclick=()=>{navigation.push({label:b.dataset.suggestLabel,url:b.dataset.suggestPath,level:0});paintMenus();});
            const pages=await request('/api/site/content?type=page');if(!form.isConnected)return;
            document.querySelector('#site-page-suggestions').innerHTML='<p class="desk-help">หน้าเนื้อหาที่สร้างไว้</p>'+pages.data.map(p=>`<button type="button" data-use-page="${p.id}">${esc(p.title)}</button>`).join('');
            root.querySelectorAll('[data-use-page]').forEach(b=>b.onclick=()=>{const p=pages.data.find(p=>p.id===Number(b.dataset.usePage));navigation.push({label:p.title.slice(0,60),url:'/portal/pages/'+p.slug,level:1});paintMenus();});
            let hubs=[];try{hubs=((await request('/api/cms/hubs')).data||[]).filter(h=>h.status==='published');}catch(e){hubs=[];}
            if(form.isConnected&&hubs.length){const box=document.querySelector('#site-page-suggestions');box.insertAdjacentHTML('beforeend','<p class="desk-help">หน้ากลุ่มงาน กลุ่มสาระ สมาคม และรายงานที่เผยแพร่แล้ว</p>'+hubs.map(h=>`<button type="button" data-use-hub="${esc(h.slug)}">${esc(h.title)}</button>`).join(''));box.querySelectorAll('[data-use-hub]').forEach(b=>b.onclick=()=>{const h=hubs.find(h=>h.slug===b.dataset.useHub);navigation.push({label:h.title.slice(0,60),url:'/portal/groups/'+h.slug,level:1});paintMenus();});}
        }
        if(page==='homepage'){
            const paintSections=()=>{document.querySelector('#site-home-sections').innerHTML=sections.map((item,index)=>`<div class="desk-home-section-row"><label><input type="checkbox" data-section-enabled="${index}" ${item.enabled?'checked':''}><span>${item.label}</span></label><div><button type="button" data-section-move="${index},-1">ขึ้น</button><button type="button" data-section-move="${index},1">ลง</button></div></div>`).join('');root.querySelectorAll('[data-section-enabled]').forEach(box=>box.onchange=()=>sections[Number(box.dataset.sectionEnabled)].enabled=box.checked);root.querySelectorAll('[data-section-move]').forEach(b=>b.onclick=()=>{const [i,d]=b.dataset.sectionMove.split(',').map(Number),j=i+d;if(j<0||j>=sections.length)return;[sections[i],sections[j]]=[sections[j],sections[i]];paintSections();});};paintSections();
            const pages=await request('/api/site/content?type=page&status=published');if(!form.isConnected)return;
            const picker=document.querySelector('#homepage-page-block');picker.innerHTML='<option value="">เลือกหน้าเนื้อหาที่เผยแพร่แล้ว</option>'+pages.data.map(p=>`<option value="page:${p.id}">${esc(p.title)}</option>`).join('');
            sections.forEach(section=>{if(section.key.startsWith('page:'))section.label=pages.data.find(p=>'page:'+p.id===section.key)?.title||'บล็อกหน้าเนื้อหา';});paintSections();
            document.querySelector('#reset-home-sections').onclick=()=>{sections=allSections(['services','news','notices','albums','events']);paintSections();};
            document.querySelector('#add-homepage-block').onclick=()=>{const key=picker.value;if(!key)return;if(sections.some(x=>x.key===key)){toast('มีส่วนเนื้อหานี้แล้ว');return;}if(sections.length>=15){toast('รองรับไม่เกิน 15 ส่วน',true);return;}sections.push({key,label:pages.data.find(p=>'page:'+p.id===key).title,enabled:true});paintSections();};
        }
        if(page==='profile'){
            const bindRemove=()=>root.querySelectorAll('[data-remove-setting-row]').forEach(b=>b.onclick=()=>b.closest('.desk-setting-pair').remove());bindRemove();
            document.querySelector('#add-site-stat').onclick=()=>{if(document.querySelectorAll('#site-statistics .desk-setting-pair').length>=6)return;document.querySelector('#site-statistics').insertAdjacentHTML('beforeend',statRow({label:'',value:''}));bindRemove();};
            document.querySelector('#add-site-social').onclick=()=>{if(document.querySelectorAll('#site-social .desk-setting-pair').length>=5)return;document.querySelector('#site-social').insertAdjacentHTML('beforeend',socialRow({label:'',url:''}));bindRemove();};
        }
        form.onsubmit=async event=>{
            event.preventDefault();if(!form.reportValidity())return;const intent=event.submitter?.value||'draft',snapshot=copy(s);
            try{
                if(page==='profile'){
                    for(const name of ['badge','intro_heading','intro_text','mission','levels','default_seo_description','footer_text','email','office_hours'])snapshot[name]=form.elements[name].value;
                if(form.elements.directory_source)snapshot.directory_source=form.elements.directory_source.value;
                    snapshot.statistics=[...form.querySelectorAll('#site-statistics .desk-setting-pair')].map(row=>({label:row.querySelector('[data-pair-label]').value,value:row.querySelector('[data-pair-value]').value}));
                    snapshot.extras=readExtras(form);snapshot.social_links=[...form.querySelectorAll('#site-social .desk-setting-pair')].map(row=>({label:row.querySelector('[data-pair-label]').value,url:row.querySelector('[data-pair-url]').value}));
                }
                if(page==='menus')snapshot.navigation=unflattenMenus(navigation);
                if(page==='homepage')snapshot.homepage_sections=sections.filter(x=>x.enabled).map(x=>x.key);
                const result=await request('/api/site/settings','PUT',{version:summary.settings.version,intent,section:['profile','menus','homepage'].includes(page)?page:null,settings:snapshot});summary.settings=result;
                Object.assign(s,result.draft);if(form.isConnected)document.querySelector('#settings-status').textContent=intent==='publish'?'ใช้การตั้งค่าบนเว็บไซต์แล้ว':'เก็บร่างแล้ว หน้าเว็บเดิมยังไม่เปลี่ยน';toast(intent==='publish'?'อัปเดตหน้าเว็บไซต์แล้ว':'เก็บฉบับร่างแล้ว');
            }catch(error){reportError(error);}
        };
    }
    function extrasCard(s){
        const x=s.extras||{},p=x.popular||{},c=x.chat||{},m=x.map||{};
        return `<section class="desk-editor-card glass" id="site-extras"><h2>ส่วนเสริมหน้าเว็บไซต์</h2><h3>ข่าวยอดนิยมและยอดอ่าน</h3>${select('นับย้อนหลัง','x_days',{7:'7 วัน',30:'30 วัน'},String(p.days??7))}${input('จำนวนข่าวที่แสดง (3 ถึง 10)','x_limit',p.limit??5,'number','min="3" max="10" step="1"')}<label class="desk-field"><span><input type="checkbox" name="x_show_views" ${x.show_views?'checked':''}> แสดงยอดอ่านในหน้าข่าว</span></label><p class="desk-help">นับเป็นยอดรวมต่อข่าวต่อวัน ไม่เก็บที่อยู่เครือข่าย รหัสเบราว์เซอร์ หรือข้อมูลผู้อ่าน เพิ่มบล็อก "ข่าวยอดนิยม" ได้ที่หน้า "จัดหน้าแรก"</p><h3>ปุ่มแชต</h3>${input('ลิงก์ Messenger (https://m.me/ชื่อเพจ)','x_messenger',c.messenger,'url','maxlength="200"')}${input('ลิงก์ LINE (https://line.me/R/ti/p/@ไอดี หรือ https://lin.ee/รหัส)','x_line',c.line,'url','maxlength="200"')}${select('ตำแหน่งปุ่ม','x_placement',{floating:'ลอยที่มุมจอ',footer:'ส่วนท้ายเว็บไซต์',both:'ทั้งสองแบบ'},c.placement||'floating')}<p class="desk-help">ปุ่มเป็นลิงก์ธรรมดา ไม่โหลดสคริปต์ เฟรม หรือฟอนต์จาก Messenger และ LINE จนกว่าผู้เยี่ยมชมจะกด</p><h3>แผนที่</h3>${select('ผู้ให้บริการแผนที่','x_provider',{google:'Google Maps',osm:'OpenStreetMap'},m.provider||'google')}${input('ละติจูด (-90 ถึง 90)','x_lat',m.lat??'','text','inputmode="decimal" maxlength="12"')}${input('ลองจิจูด (-180 ถึง 180)','x_lng',m.lng??'','text','inputmode="decimal" maxlength="13"')}${input('หรือชื่อสถานที่ (Google Maps ใช้แทนพิกัดได้)','x_query',m.query,'text','maxlength="120"')}${input('หัวข้อบล็อกแผนที่','x_map_label',m.label,'text','maxlength="80" placeholder="แผนที่โรงเรียน"')}<label class="desk-field"><span><input type="checkbox" name="x_on_contact" ${m.on_contact?'checked':''}> แสดงแผนที่ในหน้าติดต่อโรงเรียน</span></label><p class="desk-help">แผนที่แสดงเป็นภาพนิ่งก่อน และเชื่อมต่อผู้ให้บริการเมื่อผู้เยี่ยมชมกด "โหลดแผนที่" เท่านั้น เพิ่มบล็อก "แผนที่โรงเรียน" ในหน้าแรกได้ที่ "จัดหน้าแรก"</p></section>`;
    }
    function readExtras(form){
        const v=n=>form.elements[n].value.trim(),num=n=>v(n)===''?null:v(n);
        return {popular:{days:Number(v('x_days')),limit:Number(v('x_limit'))},show_views:form.elements.x_show_views.checked,chat:{messenger:v('x_messenger'),line:v('x_line'),placement:v('x_placement')},map:{provider:v('x_provider'),lat:num('x_lat'),lng:num('x_lng'),query:v('x_query'),label:v('x_map_label'),on_contact:form.elements.x_on_contact.checked}};
    }
    function statRow(stat){return `<div class="desk-setting-pair"><input aria-label="ค่าของสถิติ" data-pair-value value="${esc(stat.value)}" maxlength="50" required><input aria-label="ชื่อสถิติ" data-pair-label value="${esc(stat.label)}" maxlength="80" required><button type="button" data-remove-setting-row>นำออก</button></div>`;}
    function socialRow(social){return `<div class="desk-setting-pair"><input aria-label="ชื่อช่องทาง" data-pair-label value="${esc(social.label)}" maxlength="60" required><input aria-label="ลิงก์ช่องทาง" data-pair-url type="url" value="${esc(social.url)}" maxlength="1000" required><button type="button" data-remove-setting-row>นำออก</button></div>`;}
    function flattenMenus(items,level=0){return items.flatMap(item=>[{label:item.label,url:item.url,level},...flattenMenus(item.children||[],level+1)]);}
    function unflattenMenus(items){const roots=[],stack=[];for(const item of items){if(item.level>stack.length||item.level>2)throw Error('ระดับเมนูข้ามขั้น กรุณาเลื่อนหรือถอยรายการให้มีเมนูแม่ก่อน');const node={label:item.label,url:item.url};if(item.level===0)roots.push(node);else{const parent=stack[item.level-1];(parent.children??=[]).push(node);}stack[item.level]=node;stack.length=item.level+1;}return roots;}
    function allSections(enabled){const labels={services:'ลิงก์และบริการ',news:'ข่าวและกิจกรรม',notices:'รับสมัครงาน / จัดซื้อจัดจ้าง',albums:'อัลบั้มภาพ',events:'ปฏิทินกิจกรรม',popular:'ข่าวยอดนิยม',map:'แผนที่โรงเรียน',...(window.SaanHomeSections||{})};return [...enabled,...Object.keys(labels).filter(key=>!enabled.includes(key))].map(key=>({key,label:labels[key]||'บล็อกหน้าเนื้อหา',enabled:enabled.includes(key)}));}
    async function categoriesPage(){
        root.innerHTML=title('หมวดหมู่เนื้อหา','หมวดเนื้อหา','เปลี่ยนชื่อหมวดหรือเพิ่มหมวดใหม่ให้เหมาะกับโรงเรียน')+`<p class="desk-error" id="desk-error" role="alert"></p><section class="desk-editor-card glass"><h2>เพิ่มหมวดเนื้อหา</h2><form id="add-category" class="desk-category-form">${input('ชื่อหมวด','label','','text','required maxlength="80"')}${input('รหัสหมวด (a-z, 0-9, ขีด)','slug','','text','required pattern="[a-z][a-z0-9-]{0,29}" maxlength="30"')}<button class="primary">เพิ่มหมวด</button></form></section><section class="desk-editor-card glass"><h2>หมวดทั้งหมด</h2>${summary.categories.map(c=>`<form class="desk-category-form" data-category-form="${c.id}" data-version="${c.version}">${input('ชื่อหมวด','label',c.label,'text','required maxlength="80"')}${input('รหัสหมวด','slug',c.slug,'text','required maxlength="30"')}<button>บันทึก</button><button type="button" data-remove-category="${c.id}" data-version="${c.version}" class="desk-danger">ลบหมวด</button></form>`).join('')}</section>`;
        const save=async(event,id=null)=>{event.preventDefault();const form=event.currentTarget;try{await request('/api/site/categories'+(id?'/'+id:''),id?'PUT':'POST',{label:form.elements.label.value,slug:form.elements.slug.value,...(id?{version:Number(form.dataset.version)}:{})});await refreshSummary();await categoriesPage();toast('บันทึกหมวดแล้ว');}catch(error){reportError(error);}};
        document.querySelector('#add-category').onsubmit=save;root.querySelectorAll('[data-category-form]').forEach(form=>form.onsubmit=e=>save(e,form.dataset.categoryForm));
        root.querySelectorAll('[data-remove-category]').forEach(b=>b.onclick=async()=>{if(!confirm('ลบหมวดนี้หรือไม่? หมวดที่มีเนื้อหาใช้อยู่จะลบไม่ได้'))return;try{await request('/api/site/categories/'+b.dataset.removeCategory,'DELETE',{version:Number(b.dataset.version)});await refreshSummary();await categoriesPage();toast('ลบหมวดแล้ว');}catch(error){reportError(error);}});
    }
    async function inbox(page=1){
        const hash=location.hash;const response=await request('/api/site/messages?page='+page);if(hash!==location.hash)return;
        root.innerHTML=title('ข้อความจากผู้ติดต่อ','ข้อความติดต่อโรงเรียน','ข้อความจากหน้าเว็บไซต์ เก็บและจัดการในระบบนี้')+`<p class="desk-error" id="desk-error" role="alert"></p><section class="desk-editor-card glass">${response.data.map(message=>`<details class="desk-message"><summary><span class="tag ${message.status==='unread'?'warm':''}">${{unread:'ข้อความใหม่',read:'อ่านแล้ว',archived:'จัดเก็บแล้ว'}[message.status]}</span><strong>${esc(message.subject)}</strong><small>${esc(message.name)} · ${dateLabel(message.created_at)}</small></summary><div><p>${esc(message.email)}</p><p class="desk-message-body">${esc(message.message)}</p><div>${[['read','อ่านแล้ว'],['unread','ทำเครื่องหมายใหม่'],['archived','จัดเก็บ']].map(([status,label])=>`<button data-message="${message.id}" data-version="${message.version}" data-message-status="${status}">${label}</button>`).join('')}</div></div></details>`).join('')||'<div class="desk-empty">ยังไม่มีข้อความติดต่อ</div>'}</section>`+pagination(response);bindPagination(response,inbox);
        root.querySelectorAll('[data-message]').forEach(b=>b.onclick=async()=>{try{await request('/api/site/messages/'+b.dataset.message,'PUT',{version:Number(b.dataset.version),status:b.dataset.messageStatus});await refreshSummary();await inbox();toast('บันทึกสถานะข้อความแล้ว');}catch(error){reportError(error);}});
    }

    function pagination(response){if(response.last_page===undefined){return `<div class="desk-pagination">${response.current_page>1?`<button data-page-previous="${response.current_page-1}">ก่อนหน้า</button>`:''}<span>หน้า ${response.current_page}</span>${response.next_page_url?`<button data-page-next="${response.current_page+1}">ถัดไป</button>`:''}</div>`;}return `<div class="desk-pagination">${response.current_page>1?`<button data-page-previous="${response.current_page-1}">ก่อนหน้า</button>`:''}<span>หน้า ${response.current_page} / ${response.last_page} · ${response.total} รายการ</span>${response.current_page<response.last_page?`<button data-page-next="${response.current_page+1}">ถัดไป</button>`:''}</div>`;}
    function bindPagination(response,callback){root.querySelectorAll('[data-page-previous],[data-page-next]').forEach(b=>b.onclick=()=>callback(Number(b.dataset.pagePrevious||b.dataset.pageNext)).catch(reportError));}
    async function audit(page=1){
        const hash=location.hash;const response=await request('/api/site/audit?page='+page);if(hash!==location.hash)return;
        root.innerHTML=title('ประวัติการจัดการ','ประวัติการจัดการ','ตรวจการบันทึก เผยแพร่ และเปลี่ยนการตั้งค่า')+`<section class="desk-editor-card glass"><div class="table-wrap"><table><thead><tr><th>เวลา</th><th>รายการ</th><th>ผู้ใช้</th><th>อ้างอิง</th></tr></thead><tbody>${response.data.map(row=>`<tr><td>${esc(row.created_at)}</td><td>${esc(row.action)}</td><td>#${row.actor_id}</td><td>${esc(row.entity)} #${row.entity_id||'—'}</td></tr>`).join('')}</tbody></table></div></section>`+pagination(response);bindPagination(response,audit);
    }
})();
